// Every key with numbers also works for other numbers (5 → #).
for(const [k,v] of Object.entries(EN)){if(/\d/.test(k)){const nk=k.replace(/\d+(?:[.,]\d+)?/g,'#'),nv=v.replace(/\d+(?:[.,]\d+)?/g,'#');if(!(nk in EN)&&(k.match(/\d+/g)||[]).length===(v.match(/\d+/g)||[]).length)EN[nk]=nv}}
let i18nCache=new Map();
function enLang(){return typeof state!=='undefined'&&state.lang==='en'}
function trText(t,depth=0){
 if(depth>4)return null;
 if(Object.prototype.hasOwnProperty.call(EN,t))return EN[t];
 const nums=[];const norm=t.replace(/\d+(?:[.,]\d+)?/g,n=>{nums.push(n);return '#'});
 if(nums.length&&Object.prototype.hasOwnProperty.call(EN,norm)){let i=0;return EN[norm].replace(/#/g,()=>nums[i++]??'#')}
 for(const [re,fn] of EN_PATTERNS){if(!fn)continue;const m=t.match(re);if(m){const parts=m.slice(1).map(x=>x===undefined?x:(trText(x,depth+1)??x));const r=fn(...parts);if(r!==null)return r}}
 const q=t.match(/^”([\s\S]+)”([\s\S]*)$/);if(q){const r=trText(q[1],depth+1);if(r!==null)return '“'+r+'”'+(q[2]?(trText(q[2].trim(),depth+1)!==null?' '+trText(q[2].trim(),depth+1):q[2]):'')}
 for(const sep of [' · ',' – ',': ']){if(t.includes(sep)){const parts=t.split(sep);const tp=parts.map(p=>trText(p.trim(),depth+1));if(tp.some(x=>x!==null))return parts.map((p,i)=>tp[i]??p.trim()).join(sep)}}
 if(/[.!?] /.test(t)){const parts=t.split(/(?<=[.!?”]) (?=[A-ZÅÄÖ”+])/);if(parts.length>1){const tp=parts.map(x=>trText(x,depth+1));if(tp.some(x=>x!==null))return parts.map((x,i)=>tp[i]??x).join(' ')}}
 const sym=t.match(/^([^\p{L}\d”"]+)(.+)$/u);if(sym){const r=trText(sym[2],depth+1);if(r!==null)return sym[1]+r}
 const tail=t.match(/^(.+?)(\s*[→↗!?.:…✦✨]+)$/u);if(tail){const r=trText(tail[1],depth+1);if(r!==null)return r+tail[2]}
 return null;
}
function tr(s){
 if(!s||!/[A-Za-zÅÄÖåäö]/.test(s))return s;
 if(i18nCache.has(s))return i18nCache.get(s);
 const m=s.match(/^(\s*)([\s\S]*?)(\s*)$/),core=m[2];
 const t=trText(core);const out=t===null?s:m[1]+t+m[3];
 i18nCache.set(s,out);return out;
}
const I18N_ATTRS=['aria-label','alt','title','placeholder'];
function noTranslate(el){return el&&el.closest&&el.closest('[translate="no"],script,style,textarea,select')}
function translateTree(n){
 if(!enLang()||!n)return;
 if(n.nodeType===3){if(noTranslate(n.parentElement))return;const v=n.data,t=tr(v);if(t!==v)n.data=t;return}
 if(n.nodeType!==1||noTranslate(n))return;
 for(const a of I18N_ATTRS){const v=n.getAttribute(a);if(v){const t=tr(v);if(t!==v)n.setAttribute(a,t)}}
 for(const c of n.childNodes)translateTree(c);
}
function applyLanguage(){
 const en=enLang();document.documentElement.lang=en?'en':'sv';
 const b=$('#langToggle');if(b){b.textContent=en?'SV':'EN';b.setAttribute('aria-label',en?'Byt till svenska':'Switch to English')}
 if(en){document.title=tr(document.title);translateTree(document.body)}
}
if(typeof MutationObserver!=='undefined'&&typeof document!=='undefined'&&document.body){
 new MutationObserver(ms=>{if(!enLang())return;for(const m of ms){if(m.type==='characterData')translateTree(m.target);else if(m.type==='attributes')translateTree(m.target);else m.addedNodes.forEach(translateTree)}}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:I18N_ATTRS});
}
if(typeof document!=='undefined'&&$('#langToggle')){
 $('#langToggle').onclick=()=>{state.lang=enLang()?'sv':'en';save();if(state.lang==='sv')location.reload();else applyLanguage()};
 applyLanguage();
}
